package fraymus.workspace;

import org.json.*;
import java.awt.image.BufferedImage;
import java.util.*;

/** Fixed RGB/edge appearance plus fixed negative exemplars; never learns from scored frames. */
final class MatTarget041 {
    static final String VERSION="mat-colour-edge-negative-041-v1";
    static final int COLS=12,ROWS=20;
    private final PlaneCalibration plane;private final double[] anchor;private final List<double[]> negatives=new ArrayList<>();private final double w,h;
    private double cx,cy,angle,scale=1;private int lost;
    record Candidate(double x,double y,double sc,double angle,double score,double colour,double correlation,double edge,double negative){}
    MatTarget041(BufferedImage image,JSONArray box,JSONArray negativeBoxes,PlaneCalibration plane){
        this.plane=plane;var b=box(box);cx=(b[0]+b[2])/2;cy=(b[1]+b[3])/2;w=b[2]-b[0];h=b[3]-b[1];if(!plane.inPlane(cx,cy))throw new IllegalArgumentException("Seed centre outside measured mat");anchor=sample(image,cx,cy,w,h,0);if(anchor==null||RigidTargetTracker.variance(anchor)<.00005)throw new IllegalArgumentException("Include target edges/texture in a valid seed");
        if(negativeBoxes.isEmpty()||negativeBoxes.length()>6)throw new IllegalArgumentException("Declare1..6 real background/distractor boxes");for(Object raw:negativeBoxes){var n=box((JSONArray)raw);if(PixelTracker.iou(new PixelTracker.Box(b[0],b[1],w,h),new PixelTracker.Box(n[0],n[1],n[2]-n[0],n[3]-n[1]))>.02)throw new IllegalArgumentException("Background exemplar overlaps target");var values=sample(image,(n[0]+n[2])/2,(n[1]+n[3])/2,n[2]-n[0],n[3]-n[1],0);if(values==null)throw new IllegalArgumentException("Background patch touches camera edge");negatives.add(values);}
    }
    static double[] box(JSONArray a){if(a.length()!=4)throw new IllegalArgumentException("Use normalized x0,y0,x1,y1");var b=new double[4];for(int i=0;i<4;i++)b[i]=PlaneCalibration.bounded(a.getDouble(i),0,1);if(b[2]-b[0]<.015||b[3]-b[1]<.025||b[2]-b[0]>.5||b[3]-b[1]>.6)throw new IllegalArgumentException("Select a bounded target/background rectangle");return b;}
    static double[] sample(BufferedImage im,double x,double y,double w,double h,double angle){var a=new double[COLS*ROWS*3];double c=Math.cos(Math.toRadians(angle)),s=Math.sin(Math.toRadians(angle));int at=0;for(int iy=0;iy<ROWS;iy++)for(int ix=0;ix<COLS;ix++){double u=((ix+.5)/COLS-.5)*w,v=((iy+.5)/ROWS-.5)*h,px=(x+c*u-s*v)*im.getWidth(),py=(y+s*u+c*v)*im.getHeight();if(px<0||py<0||px>=im.getWidth()-1||py>=im.getHeight()-1)return null;int xx=(int)px,yy=(int)py;double fx=px-xx,fy=py-yy;int p=im.getRGB(xx,yy),q=im.getRGB(xx+1,yy),r=im.getRGB(xx,yy+1),t=im.getRGB(xx+1,yy+1);for(int shift=16;shift>=0;shift-=8)a[at++]=((1-fy)*((1-fx)*((p>>shift)&255)+fx*((q>>shift)&255))+fy*((1-fx)*((r>>shift)&255)+fx*((t>>shift)&255)))/255.;}return a;}
    static double similarity(double[] a,double[] b){double mse=0,edge=0,energy=0;for(int i=0;i<a.length;i++){mse+=(a[i]-b[i])*(a[i]-b[i]);if(i>=3){double da=a[i]-a[i-3],db=b[i]-b[i-3];edge+=Math.abs(da-db);energy+=Math.abs(da)+Math.abs(db);}}double colour=Math.max(0,1-Math.sqrt(mse/a.length)/.45),gradient=energy<.001?0:Math.max(0,1-edge/energy);return .55*Math.max(0,PixelTracker.correlation(a,b))+.30*colour+.15*gradient;}
    private Candidate score(BufferedImage image,double x,double y,double sc,double a){if(!plane.inPlane(x,y))return new Candidate(x,y,sc,a,-1,0,0,0,1);var p=sample(image,x,y,w*sc,h*sc,a);if(p==null)return new Candidate(x,y,sc,a,-1,0,0,0,1);double mse=0;for(int i=0;i<p.length;i++)mse+=(anchor[i]-p[i])*(anchor[i]-p[i]);double colour=Math.max(0,1-Math.sqrt(mse/p.length)/.45),correlation=PixelTracker.correlation(anchor,p),n=-1;for(var neg:negatives)n=Math.max(n,similarity(neg,p));return new Candidate(x,y,sc,a,similarity(anchor,p),colour,correlation,0,n);}
    private double overlap(Candidate a,Candidate b){return PixelTracker.iou(new PixelTracker.Box(a.x-w*a.sc/2,a.y-h*a.sc/2,w*a.sc,h*a.sc),new PixelTracker.Box(b.x-w*b.sc/2,b.y-h*b.sc/2,w*b.sc,h*b.sc));}
    JSONObject update(BufferedImage image){
        long start=System.nanoTime();var candidates=new ArrayList<Candidate>();boolean global=lost>=2;double step=global?.02:.015,range=.14;for(double sc:new double[]{Math.max(.75,scale*.95),scale,Math.min(1.3,scale*1.05)}){double x0=global?w*sc/2:Math.max(w*sc/2,cx-range),x1=global?1-w*sc/2:Math.min(1-w*sc/2,cx+range),y0=global?h*sc/2:Math.max(h*sc/2,cy-range),y1=global?1-h*sc/2:Math.min(1-h*sc/2,cy+range);for(double y=y0;y<=y1+1e-9;y+=step)for(double x=x0;x<=x1+1e-9;x+=step)candidates.add(score(image,x,y,sc,angle));}
        candidates.add(score(image,cx,cy,scale,angle));candidates.sort(Comparator.comparingDouble(Candidate::score).reversed());var seeds=new ArrayList<Candidate>();for(var c:candidates){if(c.score<0)continue;boolean distinct=true;for(var s:seeds)if(overlap(c,s)>.35){distinct=false;break;}if(distinct)seeds.add(c);if(seeds.size()==6)break;}
        var refined=new ArrayList<Candidate>();double px=1./image.getWidth(),py=1./image.getHeight();for(var seed:seeds){var best=seed;for(double a:new double[]{Math.max(-18,angle-6),angle,Math.min(18,angle+6)})for(double y=seed.y-step;y<=seed.y+step;y+=2*py)for(double x=seed.x-step;x<=seed.x+step;x+=2*px){var c=score(image,x,y,seed.sc,a);if(c.score>best.score)best=c;}var b=best;for(double y=b.y-2*py;y<=b.y+2*py;y+=.5*py)for(double x=b.x-2*px;x<=b.x+2*px;x+=.5*px){var c=score(image,x,y,b.sc,b.angle);if(c.score>best.score)best=c;}refined.add(best);}
        if(refined.isEmpty()){lost++;return new JSONObject().put("accepted",false).put("status","outside-measured-mat").put("score",-1).put("margin",0).put("lostFrames",lost).put("processingMs",(System.nanoTime()-start)/1e6);}
        refined.sort(Comparator.comparingDouble(Candidate::score).reversed());var best=refined.get(0);double other=-1;for(var c:refined)if(overlap(c,best)<.2)other=Math.max(other,c.score);for(var c:candidates)if(overlap(c,best)<.2)other=Math.max(other,c.score);double margin=best.score-other,negativeMargin=best.score-best.negative;boolean accepted=best.score>=.72&&best.colour>=.60&&margin>=.035&&negativeMargin>=.035;
        String status=accepted?(lost>0?"reacquired":"observed"):best.score>=.72?"ambiguous-or-background":"lost";if(accepted){cx=best.x;cy=best.y;scale=best.sc;angle=best.angle;lost=0;}else lost++;
        var out=new JSONObject().put("version",VERSION).put("accepted",accepted).put("status",status).put("score",best.score).put("colour",best.colour).put("correlation",best.correlation).put("margin",margin).put("negativeMargin",negativeMargin).put("angleDeg",angle).put("lostFrames",lost).put("processingMs",(System.nanoTime()-start)/1e6).put("meaning","Fixed human-seeded colour/edge appearance and background rejection, not semantic identity or probability");if(accepted)out.put("point",new JSONArray(new double[]{cx,cy})).put("box",new JSONArray(new double[]{cx-w*scale/2,cy-h*scale/2,cx+w*scale/2,cy+h*scale/2}));return out;
    }
}
